// Função principal de tradução com suporte a fallback e parâmetros
export function t(
  key: string,
  lang: string = "pt-BR",
  params?: Record<string, string | number>
): string {
  const selectedLang = TRANSLATIONS[lang as LanguageCode]
    ? (lang as LanguageCode)
    : "pt-BR";

  let text =
    TRANSLATIONS[selectedLang]?.[key] ||
    TRANSLATIONS["pt-BR"]?.[key] ||
    key;

  if (params) {
    Object.entries(params).forEach(([paramKey, value]) => {
      text = text.replace(new RegExp(`{{${paramKey}}}|{${paramKey}}`, "g"), String(value));
    });
  }

  return text;
}